// @options: {"max_output_tokens": 20000}
const ls = await tools.bash({ command: "find . -type f -not -path './node_modules/*' -not -path './.git/*' | sort", timeout: 15 });
console.log("FILES:\n" + ls.output);
const g = await tools.bash({ command: "grep -rn 'legacyLog(' . 2>/dev/null | grep -v node_modules | grep -v '/.git/'", timeout: 15 });
console.log("GREP legacyLog(:\n" + g.output);
return "explored";

// @options: {"max_output_tokens": 30000}
const files = [
  "src/lib/log.js", "src/auth/tokens.js", "src/auth/session.js", "src/util/retry.js",
  "src/jobs/report.js", "src/jobs/cleanup.js", "src/api/orders.js", "src/api/users.js",
  "src/lib/config.js", "src/index.js", "config/app.json", "config/jobs.json"
];
const results = await Promise.allSettled(files.map(f => tools.read({ path: f, offset: 1, limit: 200 })));
for (let i = 0; i < files.length; i++) {
  console.log("===== " + files[i] + " =====");
  const r = results[i];
  console.log(r.status === "fulfilled" ? String(r.value) : "ERROR: " + r.reason);
}
return "read";

// @options: {"max_output_tokens": 10000}
const keys = ["pageSize","maxOrderItems","healthPath","sessionTtlSec","maxRetries","cleanupIntervalMin","reportRecipients","syncBatchSize","archiveAfterDays"];
const r = await tools.bash({ command: "grep -rn -E '" + keys.join("|") + "' src/ ; echo '--- health.js ---'; cat src/api/health.js; echo '--- sync.js ---'; cat src/jobs/sync.js", timeout: 15 });
console.log(r.output);
return "checked";
